namespace BankingAPI.Domain.Ledger;

/// <summary>
/// A transfer from one of the user's accounts to any active account, identified by its
/// account number. The idempotency key is generated by the client once per intended transfer.
/// </summary>
public sealed record TransferRequest(Guid UserId, Guid FromAccountId, string ToAccountNumber, decimal Amount, string? Note, Guid IdempotencyKey);
